{"query": "
-- ============================================================
-- PREVIEW: First 6 months and last 6 months of sales summary
-- ============================================================
(
    SELECT 'EARLIEST' AS period, * FROM public.monthly_sales_summary ORDER BY year_month ASC  LIMIT 6
)
UNION ALL
(
    SELECT 'LATEST'   AS period, * FROM public.monthly_sales_summary ORDER BY year_month DESC LIMIT 6
)
ORDER BY year_month, period;
"}
